package br.com.mecaniQA.api.Mappers;
import java.sql.*; import br.com.mecaniQA.api.model.*; import br.com.mecaniQA.api.Enums.*;
public class PedidoPecasResultSetMapper implements ResultSetMapper<PedidoPecas>{public PedidoPecas map(ResultSet r)throws SQLException{Cliente c=new Cliente();Veiculo v=new Veiculo();OrdemServico os=OrdemServico.builder().comCliente(c).comVeiculo(v).comDescricaoProblema("Pedido carregado do banco").comStatus(StatusOrdemServico.ABERTO).build();os.setNumeroOS(r.getLong("numero_os"));PedidoPecas x=new PedidoPecas(os,StatusPedidoPecas.valueOf(r.getString("status")));x.setNumeroPedido(r.getLong("numero_pedido"));x.setFornecedor(r.getString("fornecedor"));x.setValorTotal(r.getDouble("valor_total"));x.setValorPago(r.getDouble("valor_pago"));x.setObservacoes(r.getString("observacoes"));Timestamp a=r.getTimestamp("data_atualizacao"),e=r.getTimestamp("data_entrega");x.setDataAtualizacao(a==null?null:a.toLocalDateTime());x.setDataEntrega(e==null?null:e.toLocalDateTime());return x;}}
